"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[95],{29978:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShopPerkConfig","desc":"The 70 shop perks (Perk Rework part 2): 40 Consumable (the run uses one copy\\nwhen it starts; the effect lasts the whole run) and 30 Expiring (a real-time\\nclock that starts on the first equip and never stops). Players buy them with\\ncoins and equip them in the Lobby only. `Family` = stat family label for the\\ncatalog and GUI; no rule reads it (same-family perks stack). `Buffs` are read\\nby Perk Rework part 3. `Hidden` perks need part 5\\ncode: not buyable, not equippable (a grant still lands in the inventory).\\nPer project convention, tune shop perks here, not in code.","source":{"line":14,"path":"src/ReplicatedStorage/SharedModules/Configs/ShopPerkConfig.luau"}}')}}]);